import {chromium} from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright/index.mjs'
const BASE='https://zimmermann-pr-f778-03972593.sfdc-8tgtt5-ecom1.exp-delivery.com'
const ORG='f_ecom_bkzk_002', SITE='ZimmermannAU'
const b=await chromium.launch(); const p=await (await b.newContext({viewport:{width:1440,height:1000}})).newPage()
let tok=null
p.on('response',async r=>{ if(/oauth2\/token/.test(r.url())&&!tok){try{const j=await r.json();tok=j.access_token}catch{}} })
await p.goto(BASE+'/product/4673TS251?color=GVSCP',{waitUntil:'domcontentloaded',timeout:60000}); await p.waitForTimeout(5000)
console.log('token?',!!tok)
const q=async(path)=>p.evaluate(async([u,t])=>{const r=await fetch(u,{headers:{Authorization:'Bearer '+t}});return {s:r.status,j:await r.json().catch(()=>null)}},[path,tok])
const sr=await q(`${BASE}/mobify/proxy/api/search/shopper-search/v1/organizations/${ORG}/product-search?siteId=${SITE}&q=dress&limit=50`)
console.log('search status',sr.s,'total',sr.j?.total)
const ids=(sr.j?.hits||[]).map(h=>h.productId).slice(0,40)
console.log('ids',ids.length)
// fetch masters in batches and find multi-colour + has sale tier
const out=[]
for(let i=0;i<ids.length;i+=10){
  const batch=ids.slice(i,i+10).join(',')
  const pr=await q(`${BASE}/mobify/proxy/api/product/shopper-products/v1/organizations/${ORG}/products?siteId=${SITE}&ids=${batch}&allImages=false&expand=variations,prices`)
  for(const prod of (pr.j?.data||[])){
    const vs=prod.variants||[]
    const colours=[...new Set(vs.map(v=>v.variationValues?.color).filter(Boolean))]
    const saleVars=vs.filter(v=>(v.tieredPrices||[]).length>1)
    if(colours.length>1) out.push({id:prod.id,colours:colours.slice(0,6),nVar:vs.length,nSale:saleVars.length,
      saleSample:saleVars.slice(0,2).map(v=>({pid:v.productId,vv:v.variationValues,t:v.tieredPrices.map(t=>t.price)}))})
  }
}
console.log(JSON.stringify(out.filter(o=>o.nSale>0).slice(0,5),null,1))
console.log('--- multi-colour no-sale (fallback) ---')
console.log(JSON.stringify(out.filter(o=>o.nSale===0).slice(0,3),null,1))
await b.close()
EOF
SP="$SP" node "$SP/search.mjs" 2>&1 | grep -v "console\." | tail -45

