      const vs=prod.variants||[]
      const colours=[...new Set(vs.map(v=>v.variationValues?.color).filter(Boolean))]
      const sale=vs.filter(v=>(v.tieredPrices||[]).length>1)
      const prices=[...new Set(vs.map(v=>v.price))]
      if(colours.length>1 && (sale.length>0 || prices.length>1)){
        found.push({id:prod.id,colours:colours.slice(0,4),nSale:sale.length,distinctPrices:prices.slice(0,5),
          sample:sale.slice(0,2).map(v=>({pid:v.productId,vv:v.variationValues,tiers:v.tieredPrices.map(t=>t.price)}))})
      }
    }
  }
  if(found.length>=3) break
}
console.log('scanned',seen.size,'masters'); console.log(JSON.stringify(found.slice(0,4),null,1))
await b.close()
EOF
