+import ProductView, { SFCC_COLOUR_ATTRIBUTE_ID, SFCC_SIZE_ATTRIBUTE_ID } from '../../components/product-view';
+  const [selectedSizeSelection, setSelectedSizeSelection] = useState<{colour: string; size: string; productId: string} | null>(null);
+  const handleVariationChange = useCallback((attributeId: string, value: string) => {
+    if (attributeId === SFCC_SIZE_ATTRIBUTE_ID && urlColour && productId) {
+      setSelectedSizeSelection({ colour: urlColour, size: value, productId });
+    }
+  }, [urlColour, productId]);
+  const pricingVariantId = useMemo(() => {
+    const effectiveSize =
+      selectedSizeSelection != null &&
+      selectedSizeSelection.colour === urlColour &&
+      selectedSizeSelection.productId === productId
+        ? selectedSizeSelection.size
+        : null;
+    if (!urlColour || !effectiveSize) return urlPid;
+    const match = product?.variants?.find(
+      (v: SfccVariant) =>
+        v.variationValues?.[SFCC_COLOUR_ATTRIBUTE_ID] === urlColour &&
+        v.variationValues?.[SFCC_SIZE_ATTRIBUTE_ID] === effectiveSize,
+    );
+    return match?.productId ?? urlPid;
+  }, [urlColour, selectedSizeSelection, product, urlPid, productId]);
+    () => selectVariantScopedPriceData(product, masterProductRef.current, pricingVariantId, urlColour),
+    [pricingVariantId, urlColour, product],
+                  onVariationChange={handleVariationChange}

